import React, { useState, useRef } from "react";
import "./App.css";

function App() {
  const [disease, setDisease] = useState("");
  const [intent, setIntent] = useState("");
  const [location, setLocation] = useState("");
  const [mode, setMode] = useState("fast");

  const [summary, setSummary] = useState("");
  const [publications, setPublications] = useState([]);
  const [trials, setTrials] = useState([]);
  const [loading, setLoading] = useState(false);

  const summaryRef = useRef(null);

  // 🚀 HANDLE SEARCH
  const handleSearch = async () => {
    if (!disease.trim()) {
      alert("Enter disease");
      return;
    }

    setLoading(true);

    try {
      const res = await fetch("http://localhost:8000/analyze", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          disease,
          intent,
          location,
          mode,
        }),
      });

      const data = await res.json();

      setSummary(data.insights || "");
      setPublications(data.publications || []);
      setTrials(data.clinical_trials || []);

      // 🔥 Auto scroll
      setTimeout(() => {
        summaryRef.current?.scrollIntoView({ behavior: "smooth" });
      }, 200);

    } catch (err) {
      console.error(err);
      alert("Backend error");
    }

    setLoading(false);
  };

  // ⌨️ ENTER KEY
  const handleKeyPress = (e) => {
    if (e.key === "Enter") handleSearch();
  };

  return (
    <div className="app">

      {/* LEFT SIDEBAR */}
      <div className="sidebar">
        <h1>🧠 Curalink X</h1>
        <p>AI Medical Research Copilot</p>

        <input
          type="text"
          placeholder="Disease..."
          value={disease}
          onChange={(e) => setDisease(e.target.value)}
        />

        <div className="mode-toggle">
          <button
            className={mode === "fast" ? "active" : ""}
            onClick={() => setMode("fast")}
          >
            ⚡ Fast
          </button>

          <button
            className={mode === "deep" ? "active" : ""}
            onClick={() => setMode("deep")}
          >
            🔬 Deep
          </button>
        </div>

        <div className="stats">
          <p>📄 Papers: {publications.length}</p>
          <p>🧪 Trials: {trials.length}</p>
        </div>
      </div>

      {/* MAIN CENTER */}
      <div className="main">
        <h2>Ask Medical Question</h2>

        <textarea
          placeholder="Ask your medical research question..."
          value={intent}
          onChange={(e) => setIntent(e.target.value)}
          onKeyDown={handleKeyPress}
        />

        <input
          placeholder="Location"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
        />

        <button onClick={handleSearch} disabled={loading}>
          {loading ? "⏳ Thinking..." : "Search"}
        </button>

        {/* SUMMARY */}
        {summary && (
          <div className="summary" ref={summaryRef}>
            <h3>AI Summary</h3>

            <div className="summary-content">
              {summary.split("\n").map((line, i) => (
                <p key={i}>{line}</p>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* RIGHT PANEL */}
      <div className="right">

        {/* PUBLICATIONS */}
        <div className="card">
          <h3>📚 Research Papers</h3>

          {publications.length === 0 ? (
            <p>No papers yet</p>
          ) : (
            publications.map((pub, i) => (
              <div key={i} className="item">
                <h4>{pub.title}</h4>
                <p>{pub.year}</p>
                <a href={pub.link} target="_blank" rel="noreferrer">
                  View Paper
                </a>
              </div>
            ))
          )}
        </div>

        {/* TRIALS */}
        <div className="card">
          <h3>🧪 Clinical Trials</h3>

          {trials.length === 0 ? (
            <p>No trials found</p>
          ) : (
            trials.map((t, i) => (
              <div key={i} className="item">
                <h4>{t.title}</h4>
                <p>Status: {t.status}</p>
              </div>
            ))
          )}
        </div>

        {/* WHAT IF */}
        <div className="card">
          <h3>🔮 What-if Analysis</h3>
          <input placeholder="e.g. Vitamin D" />
          <button>Simulate</button>
        </div>

      </div>
    </div>
  );
}

export default App;
